import fs from "node:fs";
import path from "node:path";

const root = process.cwd();

const relative =
  "artifacts/animated-effects/src/style.css";

const file =
  path.join(
    root,
    relative,
  );

function fail(message) {
  console.error(
    "\nERROR:",
    message,
  );
  process.exit(1);
}

if (
  !fs.existsSync(
    path.join(
      root,
      "pnpm-workspace.yaml",
    ),
  )
) {
  fail(
    "Uruchom instalator z katalogu głównego aplikacja-turnieje-live.",
  );
}

if (
  !fs.existsSync(
    file,
  )
) {
  fail(
    "Brak pliku: " +
    relative,
  );
}

let source =
  fs.readFileSync(
    file,
    "utf8",
  );

const marker =
  "AE_LIBRARY_STABILITY_PACK_21_START";

if (
  source.includes(
    marker,
  )
) {
  console.log(
    "Library Stability Pack 21 jest już zainstalowany.",
  );
  process.exit(0);
}

const stamp =
  new Date()
    .toISOString()
    .replace(
      /[:.]/g,
      "-",
    )
    .replace(
      "T",
      "_",
    )
    .replace(
      "Z",
      "",
    );

const backup =
  path.join(
    root,
    ".ae-pack-backup",
    `pack-21-library-stability-${stamp}`,
    relative,
  );

fs.mkdirSync(
  path.dirname(
    backup,
  ),
  {
    recursive:
      true,
  },
);

fs.copyFileSync(
  file,
  backup,
);

const patch =
  Buffer.from(
    "",
    "hex",
  ).toString(
    "utf8",
  );

source =
  source.trimEnd() +
  "\n\n" +
  patch.trim() +
  "\n";

fs.writeFileSync(
  file,
  source,
  "utf8",
);

const rollbackPath =
  path.join(
    root,
    "ae-library-stability-pack-21-rollback.mjs",
  );

const rollback =
`import fs from "node:fs";
import path from "node:path";

const root = process.cwd();
const target = path.join(root, ${JSON.stringify(relative)});
const backup = ${JSON.stringify(backup)};

if (!fs.existsSync(backup)) {
  console.error("Brak backupu:", backup);
  process.exit(1);
}

fs.copyFileSync(backup, target);
console.log("Library Stability Pack 21 cofnięty.");
`;

fs.writeFileSync(
  rollbackPath,
  rollback,
  "utf8",
);

console.log("");
console.log("====================================================");
console.log(" Animated Effects Library Stability Pack 21 INSTALLED");
console.log("====================================================");
console.log("");
console.log("Naprawa 1:");
console.log(" - wyłączone browser scroll anchoring dla biblioteki");
console.log(" - zmiana wysokości aktywnej karty nie powinna przesuwać kart nad nią");
console.log("");
console.log("Naprawa 2:");
console.log(" - biblioteka jest wymuszona jako jedna pionowa kolumna");
console.log(" - karta i obszar podglądu zawsze mają 100% szerokości");
console.log(" - podwójne kliknięcie korpusu karty nie może zwęzić całej listy");
console.log("");
console.log("Backup:", path.relative(root, backup));
console.log("Rollback: .\\ae-library-stability-pack-21-rollback.mjs");
console.log("");
console.log("Teraz:");
console.log("  pnpm --filter animated-effects run typecheck");
console.log("  pnpm --filter animated-effects run build");
